export interface CivTooltipProps {
	civ: CivInfo;
	isRecommended: boolean;
	leaderIcon: string;
}

const CivTooltip: Component<CivTooltipProps> = (props) => {
	const ageModel = AgeSelectModel.get();
	const choiceModel = RecommendedChoiceModel.get();
	const civ = createMemo(() => props.civ);

	const activeAbility = createMemo(
		() =>
			civ()?.perAgeAbilities.find((a) => a.age == ageModel.selectedAge.type) ??
			civ()?.perAgeAbilities.find((a) => !a.age),
	);

	const activeRecommendation = createMemo(() => choiceModel.forLeader().get(civ().civID));

	return (
		<Tooltip.Frame class="flex flex-col relative w-128">
			<div class="flex flex-row items-center justify-start">
				<For each={civ().traits}>
					{(attribute) => (
						<>
							<div class="create-game-civ-card-icon flex items-center justify-center mx-1">
								<AttributeIcon
									class="size-8"
									attribute={attribute}
								/>
							</div>

							<div class="uppercase">
								<L10n.Compose text={attribute} />
							</div>
						</>
					)}
				</For>
			</div>

			<TicketBox class="px-6 pt-4 pb-6">
				<div class="uppercase text-secondary-1 text-sm font-title">
					<L10n.Compose text={activeAbility()?.abilityTitle ?? ""} />
				</div>
				<div class="uppercase text-accent-2 text-sm font-body">
					<L10n.Compose text="LOC_UI_CREATE_GAME_CIVILIZATION_ABILITY" />
				</div>
				<L10n.Stylize
					class="create-game-markup tight"
					text={activeAbility()?.abilityText ?? ""}
				/>
			</TicketBox>

			<Show when={props.isRecommended}>
				<TicketBox class="flex flex-row items-center px-6 pt-4 pb-6">
					<Icon
						name={props.leaderIcon}
						class="size-13"
					/>
					<L10n.Stylize
						class="flex-auto create-game-markup tight"
						text={activeRecommendation()?.reason ?? ""}
					/>
				</TicketBox>
			</Show>
		</Tooltip.Frame>
	);
};

const CivChoiceExistingCivCardComponent: Component = () => {
	const ageModel = AgeSelectModel.get();
	const choiceModel = RecommendedChoiceModel.get();
	const leaderModel = LeaderSelectModel.get();
	const model = CivSelectModel.get();

	const civ = model.previousCiv()!;
	const isApexAge = createMemo(() => ageModel.selectedAge.type == civ.apexAge);

	const activeRecommendation = createMemo(() => choiceModel.forLeader().get(civ.civID));
	const isRecommended = createMemo(() => !!activeRecommendation());
	const leaderIcon = createMemo(() => leaderModel.selectedLeader().icon);

	const chooseSameCiv = createMemo(() => model.setSelectedCiv(civ));

	return (
		<VSlot class="civ-choice-card-panel img-unit-panelbox mr-6 group relative flex flex-col">
			<Tooltip initialHPosition={TooltipHorizontalPosition.CENTER}>
				<Tooltip.Trigger>
					<div
						class="civ-choice-card-image flex flex-col bg-cover bg-center"
						style={{ "background-image": `url('blp:${civ.bgImage}')` }}
					>
						<div class="flex-auto mt-16 relative">
							<div class="absolute flex civ-choice-card-gradient -top-8 left-1\/2" />
							<div class="absolute inset-0 flex flex-col items-center">
								<Icon
									class="civ-choice-card-civ-icon"
									name={`url('${civ.icon ?? ""}')`}
									isUrl={true}
								/>
								<Header class="text-2xl uppercase font-black civ-choice-card-text-gradient">
									{civ.name}
								</Header>
							</div>
						</div>
					</div>
				</Tooltip.Trigger>
				<Tooltip.Content>
					<CivTooltip
						civ={civ}
						isRecommended={isRecommended()}
						leaderIcon={leaderIcon()}
					/>
				</Tooltip.Content>
			</Tooltip>

			<div class="civ-choice-card-icon-area relative">
				<div class="civ-choice-card-icon-gradient absolute top-0 left-0 right-0 bottom-7" />
				<div class="absolute inset-0 flex flex-row items-center justify-center pt-1">
					<For each={civ.traits}>
						{(attribute) => (
							<div class="civ-choice-card-icon flex items-center justify-center mx-1">
								<AttributeIcon
									class="size-14"
									attribute={attribute}
								/>
							</div>
						)}
					</For>
					<div class="mx-4" />
					<div class="civ-choice-card-icon flex items-center justify-center mx-1">
						<AgeIcon
							ageId={civ.apexAge}
							class="size-14"
						/>
					</div>
					<div class="civ-choice-card-icon flex items-center justify-center mx-1">
						<TotIcon
							isApexAge={isApexAge()}
							class="size-14"
						/>
					</div>
				</div>
				<div class="flex items-center justify-center absolute -top-2 left-0 right-0">
					<div class="civ-choice-card-inner-filigree -scale-y-100" />
				</div>
				<div class="flex items-center justify-center absolute -bottom-2 left-0 right-0">
					<div class="civ-choice-card-inner-filigree" />
				</div>
			</div>

			<div class="flex flex-col flex-auto items-center relative">
				<div class="civ-choice-card-shadow absolute top-0 left-1 right-1" />
				<div class="flex-auto flex flex-col items-center justify-center mx-10">
					<div class="font-title uppercase text-secondary text-center">
						<L10n.Compose text="LOC_UI_AGE_TRANSITION_CURRENT_CIV_SELECTION" />
					</div>
					<Show when={isApexAge()}>
						<L10n.Compose text="LOC_UI_AGE_TRANSITION_APEX_CIV_INFO" />
					</Show>
				</div>

				<Tooltip>
					<Tooltip.Trigger>
						<AudioContextProvider segment="AgeTransition">
							<Button
								class="civ-choice-card-button mb-6 uppercase"
								onActivate={() => {
									chooseSameCiv();
									useAudio("AgeTransition/SelectCiv")("activate");
								}}
							>
								<L10n.Compose text="LOC_GENERIC_CONTINUE" />
							</Button>
						</AudioContextProvider>
					</Tooltip.Trigger>

					<Tooltip.Content>
						<CivTooltip
							civ={civ}
							isRecommended={isRecommended()}
							leaderIcon={leaderIcon()}
						/>
					</Tooltip.Content>
				</Tooltip>
			</div>

			<div class="civ-choice-card-top-filigree absolute -mt-6" />
			<div class="civ-choice-card-laurels-container flex flex-col absolute left-0 right-0 items-center justify-center">
				<div class="civ-choice-card-laurels relative">
					<div class="absolute inset-0 flex items-center justify-center pb-2">
						<div class="civ-choice-card-leader-hex" />
					</div>
					<div class="absolute inset-0 flex items-center justify-center pb-2">
						<Icon
							name={leaderIcon()}
							class="civ-choice-card-leader"
						/>
					</div>
				</div>
			</div>
		</VSlot>
	);
};

interface CivChoiceCivCardProps {
	icon: string;
	name: string;
	desc: string;
	bg: string;
}

const CivChoiceCivCard: Component<CivChoiceCivCardProps> = (props) => {
	return (
		<div class="civ-choice-rec-card relative p-2 mb-1 img-unit-panelbox">
			<div
				class="absolute inset-y-1 left-1 right-0\.5 bg-cover bg-center"
				style={{ "background-image": `url('blp:${props.bg}')` }}
			/>
			<div class="absolute inset-y-1 left-1 right-0\.5 civ-choice-rec-card-overlay" />
			<div
				class="absolute inset-1 bg-cover bg-center"
				style={{ "background-image": `url('blp:create_game_gradient1')` }}
			/>
			<div class="civ-choice-rec-card w-full flex flex-row relative">
				<div class="civ-choice-rec-card-icon-area flex items-center justify-center">
					<Icon
						class="civ-choice-rec-card-icon"
						name={`url('${props.icon ?? ""}')`}
						isUrl={true}
					/>
				</div>

				<div class="civ-choice-rec-card-text flex flex-col flex-auto justify-center">
					<div class="uppercase font-title text-xl text-tertiary-1 font-fit-shrink">
						<L10n.Compose text={props.name} />
					</div>
					<CreateGameHRule class="civ-choice-rec-card-text-spacing" />
					<L10n.Stylize
						class="text-base font-body text-accent-3"
						text={props.desc}
					/>
				</div>

				<div class="civ-choice-corner-filigree top-left" />
				<div class="civ-choice-corner-filigree top-right" />
				<div class="civ-choice-corner-filigree bottom-left" />
				<div class="civ-choice-corner-filigree bottom-right" />
			</div>
			<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
		</div>
	);
};

export const CivChoiceExistingCivCard = ComponentRegistry.register({
	name: "CivChoiceExistingCivCard",
	createInstance: CivChoiceExistingCivCardComponent,
});

export const CivChoiceChangeCivCardComponent: Component = () => {
	const model = CivSelectModel.get();
	const ageModel = AgeSelectModel.get();
	const choiceModel = RecommendedChoiceModel.get();
	const leaderModel = LeaderSelectModel.get();
	const flowContext = useScreenFlowContext();
	const numUnlockedCivs = createMemo(() => model.civs.filter((c) => !c.isLocked).length);

	const civRecommendations = createMemo(() =>
		[...choiceModel.historicalCivs(), ...choiceModel.recommendedCivs()].filter(
			(c) => c.apexAge == ageModel.nextAge.type && !c.isLocked,
		),
	);

	function selectCiv(civ: CivInfo) {
		if (!civ.isLocked) {
			model.setSelectedCiv(civ);
		}

		model.setViewCiv(civ);

		flowContext.activate("civ-select");
	}

	const leaderIcon = createMemo(() => leaderModel.selectedLeader().icon);

	return (
		<VSlot class="civ-choice-card-panel img-unit-panelbox ml-6 flex flex-col relative ">
			<AudioContextProvider segment="AgeTransition">
				<div class="civ-choice-card-more-civs-image">
					<Show when={civRecommendations().length > 0}>
						<div class="flex flex-col flex-auto relative mb-2 mb-6 mt-18 mx-20">
							<div
								class="civ-choice-rec-area text-sm flex flex-col items-center pb-2 relative"
								style={{ color: "#FFFFFF" }}
							>
								<div class="font-title uppercase text-tertiary-1 mt-2">
									<L10n.Compose text="LOC_UI_AGE_TRANSITION_RECOMMENDED_CIVILIZATIONS" />
								</div>
								<div class="uppercase text-sm text-accent-3">
									<L10n.Compose
										text="LOC_UI_AGE_TRANSITION_FOR_LEADER"
										args={[leaderModel.selectedLeader().rawName]}
									/>
								</div>

								<div class="civ-choice-rec-filigree top-left" />
								<div class="civ-choice-rec-filigree top-right" />
							</div>
							<ScrollArea
								class="flex-auto -mr-8"
								reserveSpace={true}
								useProxy={true}
							>
								<div class="civ-choice-rec-area">
									<For each={civRecommendations()}>
										{(civ) => (
											<Tooltip>
												<Tooltip.Trigger>
													<Tab.Trigger name="civ-details">
														<Activatable
															class="group"
															onActivate={() => selectCiv(civ)}
														>
															<CivChoiceCivCard
																name={civ.name}
																icon={civ.icon}
																desc={
																	choiceModel.forLeader().get(civ.civID)?.reason ?? ""
																}
																bg={civ.bgImage}
															/>
														</Activatable>
													</Tab.Trigger>
												</Tooltip.Trigger>

												<Tooltip.Content>
													<CivTooltip
														civ={civ}
														isRecommended={true}
														leaderIcon={leaderIcon()}
													/>
												</Tooltip.Content>
											</Tooltip>
										)}
									</For>
								</div>
							</ScrollArea>
						</div>
					</Show>
				</div>
				<div class="flex flex-col flex-auto items-center relative">
					<div class="civ-choice-card-shadow absolute top-0 left-1 right-1" />
					<div class="flex-auto flex flex-col items-center justify-center">
						<div class="font-title uppercase text-secondary">
							<L10n.Compose text="LOC_UI_AGE_TRANSITION_NEW_CIV_SELECTION" />
						</div>

						<div>
							<span>
								<L10n.Compose
									text="LOC_UI_AGE_TRANSITION_RECOMMENDED_CIVILIZATIONS"
									args={[numUnlockedCivs() - 1]}
								/>
							</span>
						</div>
					</div>

					<Tab.Trigger name="civ-select">
						<Button class="civ-choice-card-button mb-6">
							<L10n.Compose text="LOC_UI_AGE_TRANSITION_VIEW_CIVS" />
						</Button>
					</Tab.Trigger>
				</div>
				<div class="civ-choice-card-top-filigree absolute -mt-6" />
				<div class="civ-choice-card-laurels-container flex flex-col absolute left-0 right-0 items-center justify-center">
					<div class="civ-choice-card-laurels relative">
						<div class="absolute inset-0 flex items-center justify-center pb-2">
							<div class="civ-choice-card-leader-hex" />
						</div>
						<div class="absolute inset-0 flex items-center justify-center pb-2">
							<Icon
								name={leaderIcon()}
								class="civ-choice-card-leader"
							/>
						</div>
					</div>
				</div>
			</AudioContextProvider>
		</VSlot>
	);
};

export const CivChoiceChangeCivCard = ComponentRegistry.register({
	name: "CivChoiceChangeCivCard",
	createInstance: CivChoiceChangeCivCardComponent,
});

const CivChoiceScreenComponent: Component = () => {
	return (
		<CreateGameStage
			mode={CreateGameStageMode.None}
			header={
				<CreateGameStageHeader
					showSteps={!(ViewExperience() == UIViewExperience.Handheld) && !UI.isInGame()}
					title="LOC_UI_CREATE_GAME_CIVILIZATION_SELECT"
					hideButtonText="LOC_UI_AGE_TRANSITION_VIEW_MAP"
				/>
			}
			hideLowerHeaderFiligree={true}
		>
			<HSlot class="flex-auto relative flex flex-row items-center justify-center">
				<Tab.Trigger name="memento-select">
					<CivChoiceExistingCivCard />
				</Tab.Trigger>
				<CivChoiceChangeCivCard />
			</HSlot>
		</CreateGameStage>
	);
};

export const AgeTransitionCivChoiceScreen = ComponentRegistry.register({
	name: "AgeTransitionCivChoiceScreen",
	createInstance: CivChoiceScreenComponent,
	styles: [style],
});
